w('wordsearch.ts', "import type { AppDetailContent } from '../types';\n\nexport const content: AppDetailContent = {\n  appId: 'wordsearch',\n  locale: 'de',\n  category: 'literacy',\n\n  seo: {\n    titleTag: 'Wortsuche Generator | Suchr\u00e4tsel erstellen Kostenlos',\n    metaDescription: 'Erstellen Sie Wortsuche-R\u00e4tsel mit Bildern in Sekunden. Einstellbares Raster 5\\u201330, diagonale und r\u00fcckw\u00e4rts W\u00f6rter, 104 Themen, eigene Wortlisten. Kostenloser Generator mit PDF-Export.',\n    primaryKeyword: 'Wortsuche Generator',\n    secondaryKeywords: [\n      'Wortsuche erstellen',\n      'Suchr\u00e4tsel Generator',\n      'druckbare Wortsuche',\n      'eigene Wortsuche Generator',\n      'Wortgitter erstellen',\n    ],\n    lsiKeywords: [\n      'Wortsuche Arbeitsbl\u00e4tter',\n      'Wortschatz Aktivit\u00e4ten',\n      'Rechtschreib-Spiele',\n      'Klassen-Wortr\u00e4tsel',\n      'Worterkennung \u00dcbungen',\n      'druckbare R\u00e4tsel f\u00fcr Kinder',\n      'versteckte W\u00f6rter R\u00e4tsel',\n      'Wortsuche B\u00fccher',\n    ],\n  },\n\n  visuals: {\n    heroImages: {\n      primary: '/samples/english/wordsearch/Word Search 1.jpeg',\n      primaryAlt: 'Wortsuche-R\u00e4tsel mit Tierthema-Bildern als Worthinweise im 12x12 Raster',\n      secondary: '/samples/english/wordsearch/Word Search 2.jpeg',\n      secondaryAlt: 'Wortsuche L\u00f6sungsschl\u00fcssel mit markierten gefundenen W\u00f6rtern',\n    },\n    sampleGallery: [\n      { src: '/samples/english/wordsearch/Word Search 3.jpeg', alt: 'Wortsuche mit Lebensmittelthema und Bildhinweisen neben dem Raster', caption: 'Lebensmittelthema mit Bildhinweisen' },\n      { src: '/samples/english/wordsearch/Word Search 4.jpeg', alt: 'Gro\u00dfes 20x20 Wortsuche-Raster mit Fahrzeug-Wortschatz', caption: '20x20 Fortgeschrittenes Raster' },\n      { src: '/samples/english/wordsearch/Word Search 5.jpeg', alt: 'Wortsuche mit reiner Textliste und Natur-Rahmen', caption: 'Reine Textliste-Modus' },\n      { src: '/samples/english/wordsearch/Word Search 6.jpeg', alt: 'Wortsuche mit diagonalen und r\u00fcckw\u00e4rts W\u00f6rtern', caption: 'Diagonale und r\u00fcckw\u00e4rts W\u00f6rter' },\n      { src: '/samples/english/wordsearch/Word Search 7.jpeg', alt: 'Wortsuche mit eigener Wortliste', caption: 'Eigene Wortlisten-Modus' },\n      { src: '/samples/english/wordsearch/Word Search 8.jpeg', alt: 'Wortsuche L\u00f6sungsschl\u00fcssel mit allen markierten W\u00f6rtern', caption: 'Automatischer L\u00f6sungsschl\u00fcssel' },\n    ],\n    youtubeId: '36keBFzJbPo',\n    videoTitle: 'So erstellen Sie Wortsuche-R\u00e4tsel mit Bildern',\n  },\n\n  hero: {\n    title: 'Wortsuche Generator',\n    tagline: 'Bildgest\u00fctzte Wortsuchen, die Wortschatz\u00fcbungen in ein R\u00e4tselabenteuer verwandeln',\n    description: `Wortsuche-R\u00e4tsel geh\u00f6ren zu den beliebtesten druckbaren Produkten auf jedem Marktplatz \\u2014 und das aus gutem Grund. Sie funktionieren f\u00fcr jedes Alter, jedes Fach und jede F\u00e4higkeitsstufe. Der Wortsuche Generator nimmt das klassische Format und erweitert es mit Bildhinweisen aus einer 104-Themen-Bibliothek.\\n\\nErstellen Sie Raster von 5\\u00d75 f\u00fcr junge Anf\u00e4nger bis 30\\u00d730 f\u00fcr Erwachsene. Steuern Sie die Wortplatzierung mit Schaltern f\u00fcr diagonale und r\u00fcckw\u00e4rts (umgekehrte) W\u00f6rter. Zeigen Sie die Wortliste als nur Bilder, nur Text oder beides.\\n\\nDrei Eingabemodi: Themenbilder (deren Namen werden zu R\u00e4tselw\u00f6rtern), manuelle Bearbeitung oder eigene Wortliste f\u00fcr beliebiges Vokabular. Der Canvas-Editor f\u00fcgt Titel, Hintergr\u00fcnde und Rahmen hinzu. Jedes R\u00e4tsel exportiert mit L\u00f6sungsschl\u00fcssel. Testen Sie alle Funktionen jetzt kostenlos.`,\n  },\n\n  howItWorks: {\n    title: 'Erstellen Sie ein Wortsuche-R\u00e4tsel in 5 Schritten',\n    steps: [\n      {\n        title: 'Wortquelle w\u00e4hlen',\n        description: 'W\u00e4hlen Sie Bilder aus der 104-Themen-Bibliothek (deren Namen werden zu R\u00e4tselw\u00f6rtern), nutzen Sie manuelle Bearbeitung oder geben Sie eine eigene Wortliste ein.',\n      },\n      {\n        title: 'Rastergr\u00f6\u00dfe festlegen',\n        description: 'Passen Sie Zeilen und Spalten unabh\u00e4ngig von 5 bis 30 an. Kleinere Raster (5\\u00d75 bis 8\\u00d78) f\u00fcr junge Lernende. Gr\u00f6\\u00dfere (15\\u00d715 bis 30\\u00d730) f\u00fcr \u00e4ltere Sch\u00fcler und Erwachsene.',\n      },\n      {\n        title: 'Wortplatzierung konfigurieren',\n        description: 'Aktivieren oder deaktivieren Sie diagonale und r\u00fcckw\u00e4rts Wortplatzierung. Horizontal und vertikal sind immer enthalten. Mehr Optionen erh\u00f6hen die Schwierigkeit.',\n      },\n      {\n        title: 'Wortlisten-Anzeige w\u00e4hlen',\n        description: 'Wortliste als nur Bilder (f\u00fcr Leseanf\u00e4nger), nur Text (f\u00fcr Rechtschreibfokus) oder beides anzeigen. Diese Einstellung verwandelt das R\u00e4tsel vom Bild-Zuordnungs- zum Rechtschreib-R\u00e4tsel.',\n      },\n      {\n        title: 'R\u00e4tsel und L\u00f6sung exportieren',\n        description: 'Laden Sie R\u00e4tsel und L\u00f6sungsschl\u00fcssel als JPEG oder PDF herunter. Der L\u00f6sungsschl\u00fcssel markiert alle W\u00f6rter im Raster. Graustufen f\u00fcr tinteneffizienten Druck.',\n      },\n    ],\n  },\n\n  features: [\n    {\n      title: 'Einstellbares Raster von 5\\u00d75 bis 30\\u00d730',\n      description: 'Zeilen und Spalten unabh\u00e4ngig einstellbar f\u00fcr Raster von 25 bis 900 Zellen. Kleine Raster f\u00fcr Vorschule. Mittlere f\u00fcr Grundschule. Gro\u00dfe f\u00fcr Erwachsene.',\n    },\n    {\n      title: 'Diagonale und r\u00fcckw\u00e4rts Wortplatzierung',\n      description: 'Schalten Sie diagonale und r\u00fcckw\u00e4rts W\u00f6rter einzeln ein oder aus. Mit allen Richtungen werden R\u00e4tsel deutlich schwieriger. Weniger Optionen machen sie einfacher.',\n    },\n    {\n      title: 'Drei Wort-Eingabemodi',\n      description: 'Themenbilder als Wortquellen, manuelle Bearbeitung zum Umbenennen, oder eigene Wortliste f\u00fcr vollst\u00e4ndige Kontrolle. Wechseln Sie zwischen bildbasierten und vokabelfokussierten R\u00e4tseln.',\n    },\n    {\n      title: 'Bild-, Text- oder kombinierte Wortliste',\n      description: 'Wortliste als nur Bilder f\u00fcr Leseanf\u00e4nger, nur Text f\u00fcr Rechtschreib\u00fcbung, oder beides. Eine Einstellung ver\u00e4ndert den p\u00e4dagogischen Zweck des R\u00e4tsels.',\n    },\n    {\n      title: '104 Bildthemen',\n      description: 'Jedes Thema liefert illustrierten Wortschatz, der zu R\u00e4tselw\u00f6rtern wird. Tiere, Lebensmittel, Fahrzeuge, Natur, Sport und saisonale Themen passen R\u00e4tsel an Unterrichtseinheiten an.',\n    },\n    {\n      title: 'Vollst\u00e4ndiger Canvas-Editor',\n      description: 'F\u00fcgen Sie Titel, Sch\u00fclername-Felder und Anweisungen als Text-Overlays hinzu. Farben \u00e4ndern, Hintergr\u00fcnde und Rahmen anwenden. Ebenensteuerung, Ausrichtung, Zoom und R\u00fcckg\u00e4ngig.',\n    },\n    {\n      title: 'Automatisch generierter L\u00f6sungsschl\u00fcssel',\n      description: 'Jedes R\u00e4tsel generiert einen L\u00f6sungsschl\u00fcssel mit markierten W\u00f6rtern im Raster. Gleiches Layout f\u00fcr einfache Korrektur oder Selbstkontrolle.',\n    },\n    {\n      title: 'Doppelexport mit Graustufen',\n      description: 'Download als hochaufl\u00f6sendes JPEG oder druckfertiges PDF. Graustufen-Schalter f\u00fcr Schwarz-Wei\u00df-Druck. R\u00e4tsel und L\u00f6sungsschl\u00fcssel als separate Dateien.',\n    },\n  ],\n\n  businessUseCases: [\n    {\n      title: 'Thematische Wortsuche-B\u00fccher auf Amazon KDP verkaufen',\n      description: 'Wortsuche-B\u00fccher geh\u00f6ren zu den profitabelsten KDP-Kategorien. Stellen Sie 50\\u2013100 thematische R\u00e4tsel zusammen: \\u201eTier-Wortsuche f\u00fcr Kinder\\u201c, \\u201eLebensmittel-Wortschatz R\u00e4tsel\\u201c, \\u201eFeiertags-Wortsuchspiele\\u201c. L\u00f6sungsschl\u00fcssel am Ende.',\n      platform: 'Amazon KDP',\n    },\n    {\n      title: 'Wortschatz-R\u00e4tselpakete f\u00fcr Etsy erstellen',\n      description: 'B\u00fcndeln Sie 10\\u201320 thematische Wortsuchen als Sofort-Downloads. Schwierigkeitsgestufte Pakete: Einfach (8\\u00d78, keine Diagonalen), Mittel (12\\u00d712, Diagonalen), Schwer (20\\u00d720, alle Richtungen). \\u201eWortsuche druckbar\\u201c ist ein hochfrequenter Suchbegriff.',\n      platform: 'Etsy',\n    },\n    {\n      title: 'Fachbereichs-Ressourcen f\u00fcr TPT erstellen',\n      description: 'Nutzen Sie den eigenen Wortlisten-Modus f\u00fcr fachspezifische R\u00e4tsel: Naturwissenschafts-Vokabular, Geschichtsbegriffe, Mathe-Fachw\u00f6rter. Klassenstufenbasierte Pakete mit passenden Rastergr\u00f6\u00dfen.',\n      platform: 'Teachers Pay Teachers',\n    },\n    {\n      title: 'Saisonale und Feiertags-R\u00e4tselsammlungen erstellen',\n      description: 'Nutzen Sie Themenbilder f\u00fcr saisonale Wortsuchen: K\u00fcrbisse f\u00fcr Halloween, Schneeflocken f\u00fcr Weihnachten, Herzen f\u00fcr Valentinstag. Saisonale R\u00e4tselsammlungen verkaufen sich ganzj\u00e4hrig.',\n      platform: 'Multi-platform',\n    },\n    {\n      title: 'Mehrsprachige Wortsuche-Sets erstellen',\n      description: 'Nutzen Sie die 11-Sprachen-Unterst\u00fctzung f\u00fcr Wortsuche-Pakete in verschiedenen Sprachen. \\u201eFranz\u00f6sische Wortschatz-Wortsuche\\u201c oder \\u201eSpanische Wortsuchspiele\\u201c zielen auf Sprachlernende.',\n      platform: 'Gumroad',\n    },\n  ],\n\n  faq: [\n    {\n      question: 'Wie gro\u00df kann das Wortsuche-Raster sein?',\n      answer: 'Zeilen und Spalten unabh\u00e4ngig von 5 bis 30 einstellbar, f\u00fcr Raster von 5\\u00d75 (25 Zellen) bis 30\\u00d730 (900 Zellen). Standard ist 12\\u00d712. Kleine Raster f\u00fcr junge Lernende, gro\u00dfe f\u00fcr Erwachsene.',\n    },\n    {\n      question: 'K\u00f6nnen W\u00f6rter diagonal und r\u00fcckw\u00e4rts erscheinen?',\n      answer: 'Ja. Diagonale und r\u00fcckw\u00e4rts Wortplatzierung einzeln ein-/ausschaltbar. Mit allen Optionen k\u00f6nnen W\u00f6rter horizontal, vertikal, diagonal und r\u00fcckw\u00e4rts erscheinen. Optionen deaktivieren macht R\u00e4tsel einfacher.',\n    },\n    {\n      question: 'Kann ich eine eigene Wortliste statt Bildern verwenden?',\n      answer: 'Ja. Der eigene Wortlisten-Modus l\u00e4sst Sie beliebige W\u00f6rter eingeben. Der Generator erstellt das R\u00e4tsel ohne Bilder. Perfekt f\u00fcr Rechtschreibleisten, Fachbegriffe oder thematische R\u00e4tsel in jeder Sprache.',\n    },\n    {\n      question: 'Kann ich nur Bilder ohne Textw\u00f6rter anzeigen?',\n      answer: 'Ja. Die Option \\u201eNur Bilder anzeigen\\u201c zeigt Bildhinweise ohne Text \\u2014 macht das R\u00e4tsel f\u00fcr Leseanf\u00e4nger zug\u00e4nglich. Auch nur Text oder beides m\u00f6glich.',\n    },\n    {\n      question: 'Werden L\u00f6sungsschl\u00fcssel generiert?',\n      answer: 'Ja. Jedes R\u00e4tsel generiert einen L\u00f6sungsschl\u00fcssel mit markierten W\u00f6rtern. Gleiches Layout, Export als separate JPEG- oder PDF-Datei.',\n    },\n    {\n      question: 'Wie viele Themen sind verf\u00fcgbar?',\n      answer: 'Das Full Access Pack enth\u00e4lt alle 104 Themen. Das Commercial Pack beliebte Themen. Beide unterst\u00fctzen eigene Bild-Uploads und eigene Wortlisten.',\n    },\n    {\n      question: 'Kann ich die R\u00e4tsel verkaufen?',\n      answer: 'Ja. Sowohl das Commercial Pack ($27) als auch das Full Access Pack ($47) enthalten eine kommerzielle Lizenz. Verkaufen Sie auf Etsy, Amazon KDP, TPT und \u00fcberall. Unbegrenzte Erstellung.',\n    },\n    {\n      question: 'Was ist der Unterschied zwischen Commercial Pack und Full Access Pack?',\n      answer: 'Das Commercial Pack ($27) enth\u00e4lt Generator, kommerzielle Lizenz, beliebte Themen und alle 11 Sprachen. Das Full Access Pack ($47) bietet zus\u00e4tzlich alle 104 Themen, bevorzugten Zugang und Updates. Beide Einmalk\u00e4ufe.',\n    },\n    {\n      question: 'Kann ich es kostenlos testen?',\n      answer: 'Ja. Alle Rastergr\u00f6\u00dfen, Wortplatzierungsoptionen und Eingabemodi funktionieren kostenlos. Einziger Unterschied ist ein Wasserzeichen. Keine Anmeldung.',\n    },\n    {\n      question: 'Welche Sprachen werden unterst\u00fctzt?',\n      answer: 'Oberfl\u00e4che und Bildbibliothek unterst\u00fctzen 11 Sprachen: Englisch, Deutsch, Franz\u00f6sisch, Spanisch, Portugiesisch, Italienisch, Niederl\u00e4ndisch, Schwedisch, D\u00e4nisch, Norwegisch und Finnisch. Eigene Wortlisten funktionieren mit jeder Sprache.',\n    },\n    {\n      question: 'Wie ist Ihre R\u00fcckerstattungsrichtlinie?',\n      answer: 'Alle Verk\u00e4ufe sind endg\u00fcltig aufgrund der digitalen Natur des Produkts. Sobald ein Lizenzschl\u00fcssel geliefert und aktiviert wurde, kann er nicht zur\u00fcckgegeben werden. Testen Sie zuerst die kostenlose Version.',\n    },\n  ],\n\n  internalLinks: [\n    { slug: 'crossword', pageType: 'app', anchorText: 'Kreuzwortr\u00e4tsel Generator' },\n    { slug: 'word-scramble', pageType: 'app', anchorText: 'Buchstabensalat Generator' },\n    { slug: 'cryptogram', pageType: 'app', anchorText: 'Kryptogramm Generator' },\n    { slug: 'word-guess', pageType: 'app', anchorText: 'Wortr\u00e4tsel Generator' },\n    { slug: 'alphabet-train', pageType: 'app', anchorText: 'Alphabet-Zug Generator' },\n    { slug: 'treasure-hunt', pageType: 'app', anchorText: 'Schatzsuche Generator' },\n    { slug: 'wordsearch', pageType: 'tool', anchorText: 'Wortsuche Generator kostenlos testen' },\n    { slug: 'literacy-bundle', pageType: 'bundle', anchorText: 'Buchstaben & W\u00f6rter Bundle \\u2014 Sparen Sie bei allen Lese-Generatoren' },\n    { slug: 'create-word-search-books', pageType: 'guide', anchorText: 'So erstellen Sie Wortsuche-B\u00fccher' },\n    { slug: 'reading-printable-ideas', pageType: 'idea', anchorText: 'Lese-Druckvorlagen Nischen-Ideen' },\n  ],\n};\n");

