w('cryptogram.ts', "import type { AppDetailContent } from '../types';\n\nexport const content: AppDetailContent = {\n  appId: 'cryptogram',\n  locale: 'de',\n  category: 'literacy',\n\n  seo: {\n    titleTag: 'Kryptogramm Generator | Bild-Code R\u00e4tsel Kostenlos',\n    metaDescription: 'Erstellen Sie Bild-Kryptogramm-R\u00e4tsel, bei denen Bilder Buchstaben ersetzen. Eigene S\u00e4tze, Hinweis-Enth\u00fcllungen, 104 Themen. Kostenloser Generator mit L\u00f6sungsschl\u00fcssel und PDF-Export.',\n    primaryKeyword: 'Kryptogramm Generator',\n    secondaryKeywords: [\n      'Kryptogramm Arbeitsbl\u00e4tter druckbar',\n      'Bild-Kryptogramm R\u00e4tsel',\n      'Bild-Code Arbeitsbl\u00e4tter',\n      'Geheimbotschaft entschl\u00fcsseln',\n      'Geheime Nachricht R\u00e4tsel',\n    ],\n    lsiKeywords: [\n      'Chiffre Arbeitsbl\u00e4tter Kinder',\n      'Entschl\u00fcsselungs-Aktivit\u00e4ten',\n      'visuelle Code R\u00e4tsel',\n      'Buchstaben-Substitution Arbeitsbl\u00e4tter',\n      'Geheimcode Aktivit\u00e4ten',\n      'Logisches Denken R\u00e4tsel',\n      'Lese-R\u00e4tsel druckbar',\n      'Entschl\u00fcsselungs-Arbeitsbl\u00e4tter',\n    ],\n  },\n\n  visuals: {\n    heroImages: {\n      primary: '/samples/english/cryptogram/cryptogram_worksheet (1).jpeg',\n      primaryAlt: 'Bild-Kryptogramm R\u00e4tsel mit Tierbildern, die Buchstaben in einem Geheimsatz ersetzen',\n      secondary: '/samples/english/cryptogram/cryptogram_worksheet (2).jpeg',\n      secondaryAlt: 'Kryptogramm L\u00f6sungsschl\u00fcssel mit Bild-zu-Buchstaben Zuordnung',\n    },\n    sampleGallery: [\n      { src: '/samples/english/cryptogram/cryptogram_worksheet (3).jpeg', alt: 'Kryptogramm mit Lebensmittelthema-Bildern als Buchstabenersatz', caption: 'Lebensmittelthema-Chiffre' },\n      { src: '/samples/english/cryptogram/cryptogram_worksheet (4).jpeg', alt: 'Kryptogramm mit 3 enth\u00fcllten Hinweisbuchstaben', caption: '3 Buchstaben-Hinweise' },\n      { src: '/samples/english/cryptogram/cryptogram_worksheet (5).jpeg', alt: 'Mehrzeiliges Kryptogramm mit Fahrzeugbildern', caption: 'Mehrzeilige S\u00e4tze' },\n      { src: '/samples/english/cryptogram/cryptogram_worksheet (6).jpeg', alt: 'Kryptogramm mit Rahmen und Hintergrunddekoration', caption: 'Eigener Hintergrund und Rahmen' },\n      { src: '/samples/english/cryptogram/cryptogram_worksheet (7).jpeg', alt: 'Kryptogramm mit manuell zugewiesenen Bildern pro Buchstabe', caption: 'Manuelle Bildzuweisung' },\n      { src: '/samples/english/cryptogram/cryptogram_worksheet (8).jpeg', alt: 'Kryptogramm L\u00f6sungsschl\u00fcssel mit entschl\u00fcsseltem Satz', caption: 'Automatischer L\u00f6sungsschl\u00fcssel' },\n    ],\n    youtubeId: '9U0BIIjCnco',\n    videoTitle: 'So erstellen Sie Bild-Kryptogramm-R\u00e4tsel',\n  },\n\n  hero: {\n    title: 'Kryptogramm Generator',\n    tagline: 'Geheimbotschaften in Bildern versteckt \\u2014 wo jedes Bild ein Buchstabe ist, der darauf wartet, entschl\u00fcsselt zu werden',\n    description: `Kryptogramme verwandeln Lesen in Detektivarbeit. Jeder Buchstabe eines Geheimsatzes wird durch ein Bild ersetzt, und Sch\u00fcler m\u00fcssen den Code knacken, indem sie herausfinden, welches Bild welchen Buchstaben darstellt. Der Kryptogramm Generator erstellt diese bildbasierten Chiffre-R\u00e4tsel mit Ihren eigenen S\u00e4tzen und Bildern aus der 104-Themen-Bibliothek.\\n\\nGeben Sie einen beliebigen Satz ein und der Generator ordnet jedem einzigartigen Buchstaben ein anderes Bild zu. Ein konfigurierbares Hinweissystem l\u00e4sst Sie einige Buchstaben enth\u00fcllen \\u2014 0 f\u00fcr reine Herausforderung, bis zur H\u00e4lfte des Alphabets f\u00fcr gef\u00fchrte Einf\u00fchrung.\\n\\nManuelle Bildzuweisung gibt kreative Kontrolle. Klicken Sie auf einzelne Buchstaben und weisen Sie bestimmte Bilder zu. Die Satzeingabe akzeptiert jeden Text \\u2014 Vokabels\u00e4tze, motivierende Zitate, Rechtschreibs\u00e4tze oder Feiertags-Geheimbotschaften. Der Canvas-Editor f\u00fcgt professionelles Design hinzu. Testen Sie es jetzt kostenlos.`,\n  },\n\n  howItWorks: {\n    title: 'Erstellen Sie ein Bild-Kryptogramm in 5 Schritten',\n    steps: [\n      {\n        title: 'Ihren Geheimsatz eingeben',\n        description: 'Geben Sie einen beliebigen Satz oder eine Nachricht ein. Der Generator identifiziert jeden einzigartigen Buchstaben und erstellt eine Bild-zu-Buchstaben Zuordnung. Mehrzeilige S\u00e4tze f\u00fcr l\u00e4ngere Nachrichten.',\n      },\n      {\n        title: 'Bilder Buchstaben zuweisen',\n        description: 'Nutzen Sie Auto-Zuweisung f\u00fcr zuf\u00e4llige Zuordnung aus dem gew\u00e4hlten Thema. Oder klicken Sie manuell auf jeden Buchstaben und w\u00e4hlen Sie ein bestimmtes Bild aus der Bibliothek.',\n      },\n      {\n        title: 'Hinweis-Enth\u00fcllungen einstellen',\n        description: 'W\u00e4hlen Sie, wie viele Buchstaben als Hinweise enth\u00fcllt werden (0 f\u00fcr keine bis zur H\u00e4lfte des Alphabets). Enth\u00fcllte Buchstaben erscheinen als Text neben den Bildern als Startpunkte.',\n      },\n      {\n        title: 'Layout konfigurieren',\n        description: 'Maximale Zeilenanzahl pro Satz einstellen. Seitengr\u00f6\u00dfe, Schriftart und Ausrichtung w\u00e4hlen. Titel und Anweisungen mit dem Canvas-Editor hinzuf\u00fcgen.',\n      },\n      {\n        title: 'R\u00e4tsel und L\u00f6sung exportieren',\n        description: 'Laden Sie Kryptogramm und L\u00f6sungsschl\u00fcssel als JPEG oder PDF herunter. Der L\u00f6sungsschl\u00fcssel zeigt die vollst\u00e4ndige Bild-Buchstaben-Zuordnung und den entschl\u00fcsselten Satz.',\n      },\n    ],\n  },\n\n  features: [\n    {\n      title: 'Eigene Satzeingabe',\n      description: 'Geben Sie beliebige S\u00e4tze, Zitate oder Nachrichten ein. Der Generator ordnet jedem einzigartigen Buchstaben ein anderes Bild zu. Vokabels\u00e4tze, R\u00e4tsel, Feiertags-Nachrichten oder Rechtschreib\u00fcbungen \\u2014 jeder Text funktioniert.',\n    },\n    {\n      title: 'Manuelle und automatische Bild-Buchstaben-Zuweisung',\n      description: 'Auto-Zuweisung ordnet Themenbilder zuf\u00e4llig zu. Manuelle Zuweisung l\u00e4sst Sie pro Buchstabe (A bis Z) ein bestimmtes Bild w\u00e4hlen. Beide Ans\u00e4tze kombinierbar.',\n    },\n    {\n      title: 'Konfigurierbare Hinweis-Enth\u00fcllungen',\n      description: 'Legen Sie fest, wie viele Buchstaben entschl\u00fcsselt als Hinweise erscheinen. Null Enth\u00fcllungen f\u00fcr reine R\u00e4tsel. Mehr Enth\u00fcllungen unterst\u00fctzen j\u00fcngere L\u00f6ser. Schwierigkeit mit einer Einstellung \u00e4ndern.',\n    },\n    {\n      title: 'Mehrzeilige Satz-Unterst\u00fctzung',\n      description: 'Legen Sie die maximale Zeilenanzahl fest, um den Satzumbruch zu steuern. K\u00fcrzere S\u00e4tze passen auf eine Zeile. L\u00e4ngere Zitate oder Abs\u00e4tze flie\u00dfen \u00fcber mehrere Zeilen.',\n    },\n    {\n      title: '104 Bildthemen',\n      description: 'Jedes Thema liefert Bilder als Buchstabenersatz. Tiere, Lebensmittel, Fahrzeuge, Natur und saisonale Themen machen jedes Kryptogramm visuell einzigartig.',\n    },\n    {\n      title: 'Eigene Bilder hochladen',\n      description: 'Laden Sie eigene Bilder als Chiffre-Symbole hoch. Klassenfotos, eigene Illustrationen oder markenspezifische Bilder verwenden.',\n    },\n    {\n      title: 'Vollst\u00e4ndiger Canvas-Editor',\n      description: 'F\u00fcgen Sie Text, Titel und Anweisungen hinzu. Farben \u00e4ndern, Hintergr\u00fcnde und Rahmen anwenden. Ebenensteuerung, Ausrichtung, Zoom und R\u00fcckg\u00e4ngig.',\n    },\n    {\n      title: 'Vollst\u00e4ndiger L\u00f6sungsschl\u00fcssel',\n      description: 'Jedes Kryptogramm generiert einen L\u00f6sungsschl\u00fcssel mit der vollst\u00e4ndigen Bild-Buchstaben-Zuordnungstabelle und dem entschl\u00fcsselten Satz. Export als JPEG oder PDF mit Graustufen-Option.',\n    },\n  ],\n\n  businessUseCases: [\n    {\n      title: 'Geheimbotschafts-R\u00e4tselb\u00fccher auf Amazon KDP erstellen',\n      description: 'Stellen Sie 50\\u2013100 Kryptogramm-R\u00e4tsel zu thematischen B\u00fcchern zusammen: \\u201eTier-Code R\u00e4tsel\\u201c, \\u201eEntschl\u00fcssle die Feiertags-Nachricht\\u201c. L\u00f6sungsschl\u00fcssel am Ende. Kryptogramm-B\u00fccher f\u00fcllen eine einzigartige Nische.',\n      platform: 'Amazon KDP',\n    },\n    {\n      title: 'Thematische Kryptogramm-Pakete auf Etsy verkaufen',\n      description: 'B\u00fcndeln Sie 10\\u201320 Bild-Kryptogramme nach Thema oder Anlass. Feiertags-Nachrichten, motivierende Zitate-Entschl\u00fcsselung und Wortschatz-Chiffre-Bl\u00e4tter bieten einzigartige Produkte.',\n      platform: 'Etsy',\n    },\n    {\n      title: 'Logisches Denken Ressourcen f\u00fcr TPT erstellen',\n      description: 'Erstellen Sie wortschatzfokussierte Kryptogramme, deren entschl\u00fcsselte S\u00e4tze Wissenschafts-Definitionen, historische Fakten oder Grammatikregeln sind. Lehrer suchen nach \\u201elogisches Denken Aktivit\u00e4ten\\u201c.',\n      platform: 'Teachers Pay Teachers',\n    },\n    {\n      title: 'Feiertags-Party-Aktivit\u00e4ten erstellen',\n      description: 'Erstellen Sie saisonale Kryptogramm-Bl\u00e4tter f\u00fcr Klassenfeiern: entschl\u00fcssle \\u201eSU\\u0308SSES ODER SAURES\\u201c f\u00fcr Halloween, \\u201eFROHES NEUES JAHR\\u201c f\u00fcr Januar. Einfach zu verteilen und motivierend.',\n      platform: 'Multi-platform',\n    },\n    {\n      title: 'Escape-Room R\u00e4tselsets entwickeln',\n      description: 'Erstellen Sie Kryptogramm-R\u00e4tsel als Komponenten druckbarer Escape-Room-Kits. Jedes gel\u00f6ste Kryptogramm enth\u00fcllt einen Hinweis f\u00fcr das n\u00e4chste R\u00e4tsel. Als Klassen- oder Familienaktivit\u00e4t verpacken.',\n      platform: 'Gumroad',\n    },\n  ],\n\n  faq: [\n    {\n      question: 'Wie funktionieren Bild-Kryptogramme?',\n      answer: 'Jeder Buchstabe eines Satzes wird durch ein Bild ersetzt. Sch\u00fcler m\u00fcssen herausfinden, welches Bild welchen Buchstaben darstellt, indem sie Wortmuster, Buchstabenh\u00e4ufigkeit und Kontext analysieren. Das Ergebnis ist eine entschl\u00fcsselte Geheimbotschaft.',\n    },\n    {\n      question: 'Kann ich einen beliebigen Satz eingeben?',\n      answer: 'Ja. Geben Sie beliebigen Text in die Satzeingabe ein. Der Generator ordnet jedem einzigartigen Buchstaben automatisch ein Bild zu. Vokabels\u00e4tze, Zitate, R\u00e4tsel oder Feiertagsnachrichten \\u2014 jeder Text funktioniert.',\n    },\n    {\n      question: 'Kann ich w\u00e4hlen, welches Bild welchen Buchstaben darstellt?',\n      answer: 'Ja. Manuelle Zuweisung l\u00e4sst Sie pro Buchstabe ein bestimmtes Bild ausw\u00e4hlen. Oder Auto-Zuweisung f\u00fcr zuf\u00e4llige Zuordnung. Beides kombinierbar.',\n    },\n    {\n      question: 'Wie funktionieren die Hinweis-Enth\u00fcllungen?',\n      answer: 'Legen Sie fest, wie viele Buchstaben als Starthinweise entschl\u00fcsselt erscheinen. Mehr Enth\u00fcllungen machen das R\u00e4tsel einfacher. Null Enth\u00fcllungen erzeugen ein reines R\u00e4tsel ohne Hinweise.',\n    },\n    {\n      question: 'Werden L\u00f6sungsschl\u00fcssel generiert?',\n      answer: 'Ja. Jedes Kryptogramm generiert einen L\u00f6sungsschl\u00fcssel mit vollst\u00e4ndiger Bild-Buchstaben-Zuordnung und entschl\u00fcsseltem Satz. Beide als JPEG und PDF exportierbar.',\n    },\n    {\n      question: 'Wie viele Themen sind verf\u00fcgbar?',\n      answer: 'Das Full Access Pack enth\u00e4lt alle 104 Themen. Das Commercial Pack beliebte Themen. Beide unterst\u00fctzen eigene Bild-Uploads.',\n    },\n    {\n      question: 'Kann ich die R\u00e4tsel kommerziell verkaufen?',\n      answer: 'Ja. Sowohl das Commercial Pack ($27) als auch das Full Access Pack ($47) enthalten eine kommerzielle Lizenz. Verkaufen Sie auf Etsy, Amazon KDP, TPT und jeder Plattform. Unbegrenzte Erstellung.',\n    },\n    {\n      question: 'Was ist der Unterschied zwischen Commercial Pack und Full Access Pack?',\n      answer: 'Das Commercial Pack ($27) enth\u00e4lt Generator, kommerzielle Lizenz, beliebte Themen und alle Sprachen. Das Full Access Pack ($47) bietet zus\u00e4tzlich alle 104 Themen, bevorzugten Zugang und Updates. Einmalk\u00e4ufe.',\n    },\n    {\n      question: 'Kann ich es kostenlos testen?',\n      answer: 'Ja. Alle Funktionen kostenlos nutzbar \\u2014 nur mit Wasserzeichen auf Exporten. Keine Anmeldung erforderlich.',\n    },\n    {\n      question: 'Welche Sprachen werden unterst\u00fctzt?',\n      answer: 'Die Oberfl\u00e4che unterst\u00fctzt 11 Sprachen. Kryptogramm ist sprachsensitiv \\u2014 die Bildbibliothek bietet lokalisierte Namen, und S\u00e4tze k\u00f6nnen in jeder Sprache eingegeben werden.',\n    },\n    {\n      question: 'Wie ist Ihre R\u00fcckerstattungsrichtlinie?',\n      answer: 'Alle Verk\u00e4ufe sind endg\u00fcltig aufgrund der digitalen Natur des Produkts. Sobald ein Lizenzschl\u00fcssel geliefert und aktiviert wurde, kann er nicht zur\u00fcckgegeben werden. Testen Sie zuerst die kostenlose Version.',\n    },\n  ],\n\n  internalLinks: [\n    { slug: 'code-addition', pageType: 'app', anchorText: 'Code-Addition Generator' },\n    { slug: 'wordsearch', pageType: 'app', anchorText: 'Wortsuche Generator' },\n    { slug: 'word-scramble', pageType: 'app', anchorText: 'Buchstabensalat Generator' },\n    { slug: 'word-guess', pageType: 'app', anchorText: 'Wortr\u00e4tsel Generator' },\n    { slug: 'crossword', pageType: 'app', anchorText: 'Kreuzwortr\u00e4tsel Generator' },\n    { slug: 'treasure-hunt', pageType: 'app', anchorText: 'Schatzsuche Generator' },\n    { slug: 'cryptogram', pageType: 'tool', anchorText: 'Kryptogramm Generator kostenlos testen' },\n    { slug: 'literacy-bundle', pageType: 'bundle', anchorText: 'Buchstaben & W\u00f6rter Bundle \\u2014 Sparen Sie bei allen Lese-Generatoren' },\n    { slug: 'create-puzzle-books', pageType: 'guide', anchorText: 'So erstellen Sie R\u00e4tselb\u00fccher' },\n    { slug: 'reading-printable-ideas', pageType: 'idea', anchorText: 'Lese-Druckvorlagen Nischen-Ideen' },\n  ],\n};\n");

